template <unsigned BASE_BITS, typename Char, typename UInt>
auto write_grouped_int(buffer_appender<Char> out, UInt value,
                       unsigned prefix, const format_specs<Char>& specs,
                       const digit_grouping<Char>& grouping,
                       bool upper = false) -> void {
  int num_digits = count_digits<BASE_BITS>(value);
  char raw[num_bits<UInt>() / BASE_BITS + 1];
  format_uint<BASE_BITS>(raw, value, num_digits, upper);

  int digits_count = num_digits;
  if (specs.align != align::numeric && specs.precision > digits_count)
    digits_count = specs.precision;
  if (specs.align == align::numeric) {
    while (to_unsigned(prefix >> 24) + to_unsigned(digits_count) +
               to_unsigned(grouping.count_separators(digits_count)) <
           to_unsigned(specs.width))
      ++digits_count;
  }
  std::string digits(to_unsigned(digits_count - num_digits), '0');
  digits.append(raw, to_unsigned(num_digits));
  auto size = to_unsigned(prefix >> 24) + to_unsigned(digits_count) +
              to_unsigned(grouping.count_separators(digits_count));
  write_padded<align::right>(out, specs, size, size, [&](reserve_iterator<buffer_appender<Char>> it) {
    for (unsigned p = prefix & 0xffffff; p != 0; p >>= 8)
      *it++ = static_cast<Char>(p & 0xff);
    return grouping.apply(it, string_view(digits.data(), digits.size()));
  });
}

