  using time_point = std::chrono::time_point<std::chrono::system_clock, Duration>;

  static int fractional_precision() {
    std::intmax_t denominator = Duration::period::den;
    int twos = 0;
    int fives = 0;
    while (denominator % 2 == 0) {
      denominator /= 2;
      ++twos;
    }
    while (denominator % 5 == 0) {
      denominator /= 5;
      ++fives;
    }
    int precision = twos > fives ? twos : fives;
    return denominator == 1 && precision <= 18 ? precision : 6;
  }

  template <typename FormatContext>
  auto format(time_point val, FormatContext& ctx) -> decltype(ctx.out()) {
    auto sys_time = std::chrono::time_point_cast<
        std::chrono::system_clock::duration>(val);
    std::tm time = localtime(sys_time);

    // strftime doesn't preserve subsecond precision. Keep its seconds output,
    // but insert a marker after %S and %T so the fraction can be appended.
    basic_memory_buffer<Char> format;
    bool has_seconds = false;
    auto specs = this->specs;
    for (std::size_t i = 0; i < specs.size();) {
      if (specs[i] != '%' || i + 1 == specs.size()) {
        format.push_back(specs[i++]);
        continue;
      }
      if (specs[i + 1] == '%') {
        format.push_back(specs[i++]);
        format.push_back(specs[i++]);
        continue;
