      if (specs[i + 1] == 'S') {
        format.append(specs.begin() + i, specs.begin() + i + 2);
        format.push_back(static_cast<Char>(0x1f));
        has_seconds = true;
        i += 2;
        continue;
      }
      if (specs[i + 1] == 'T') {
        const char time_format[] = "%H:%M:%S";
        for (auto c : time_format) {
          if (c == '\0') break;
          format.push_back(static_cast<Char>(c));
        }
        format.push_back(static_cast<Char>(0x1f));
        has_seconds = true;
        i += 2;
        continue;
      }
      format.push_back(specs[i++]);
      format.push_back(specs[i++]);
    }

    if (!has_seconds) return formatter<std::tm, Char>::format(time, ctx);

    const int precision = fractional_precision();
    std::uint64_t scale = 1;
    for (int i = 0; i < precision; ++i) scale *= 10;
    std::uint64_t fraction = 0;
    if (precision > 0) {
      const std::intmax_t denominator = Duration::period::den;
      using rep = typename Duration::rep;
