template <typename Char, typename Duration>
struct formatter<std::chrono::time_point<std::chrono::system_clock, Duration>,
                 Char> : formatter<std::tm, Char> {
 private:
  static int fractional_second_precision() {
    using period = typename Duration::period;
    int denominator = period::den;
    int twos = 0, fives = 0;
    while (denominator % 2 == 0 && twos < 18) {
      denominator /= 2;
      ++twos;
    }
    while (denominator % 5 == 0 && fives < 18) {
      denominator /= 5;
      ++fives;
    }
    return denominator == 1 ? (twos > fives ? twos : fives) : 18;
  }

 public:
  template <typename FormatContext>
  auto format(std::chrono::time_point<std::chrono::system_clock, Duration> val,
              FormatContext& ctx) const -> decltype(ctx.out()) {
    std::tm time = localtime(val);
    auto out = ctx.out();
    auto precision = fractional_second_precision();
    auto whole_seconds =
        std::chrono::duration_cast<std::chrono::seconds>(val.time_since_epoch());
    auto fraction = val.time_since_epoch() - whole_seconds;
    if (fraction < decltype(fraction)::zero())
      fraction = fraction + std::chrono::seconds(1);
    auto fraction_count = std::chrono::duration_cast<
        std::chrono::duration<std::int64_t, std::atto>>(fraction).count();
    for (int i = precision; i < 18; ++i) fraction_count /= 10;

    formatter<std::tm, Char> tm_formatter;
    auto format_range = [&](const Char* begin, const Char* end) {
      tm_formatter.specs = basic_string_view<Char>(
          begin, detail::to_unsigned(end - begin));
      out = tm_formatter.format(time, ctx);
      ctx.advance_to(out);
    };
    auto write_fraction = [&] {
      if (precision == 0) return;
      *out++ = static_cast<Char>('.');
      Char digits[18];
      int count = 0;
      do {
        digits[count++] = static_cast<Char>('0' + fraction_count % 10);
        fraction_count /= 10;
      } while (fraction_count != 0);
      for (int i = count; i < precision; ++i)
        *out++ = static_cast<Char>('0');
      while (count != 0) *out++ = digits[--count];
      ctx.advance_to(out);
    };

    auto begin = this->specs.begin();
    auto end = this->specs.end();
    auto segment_begin = begin;
    for (auto it = begin; it != end; ++it) {
      if (*it != static_cast<Char>('%') || it + 1 == end) continue;
      auto directive_size = 0;
      if (*(it + 1) == static_cast<Char>('S') ||
          *(it + 1) == static_cast<Char>('T')) {
        directive_size = 2;
      } else if (*(it + 1) == static_cast<Char>('O') && it + 2 != end &&
                 *(it + 2) == static_cast<Char>('S')) {
        directive_size = 3;
      }
      if (directive_size == 0) continue;
      format_range(segment_begin, it);
      format_range(it, it + directive_size);
      write_fraction();
      it += directive_size - 1;
      segment_begin = it + 1;
    }
    format_range(segment_begin, end);
    return out;
  }
};

