struct formatter<std::chrono::time_point<std::chrono::system_clock, Duration>,
                 Char> : formatter<std::tm, Char> {
  template <typename FormatContext>
  auto format(std::chrono::time_point<std::chrono::system_clock, Duration> val,
              FormatContext& ctx) -> decltype(ctx.out()) {
    std::tm time = localtime(val);

    int precision = 0;
    auto denominator = Duration::period::den;
    while (denominator % 2 == 0) {
      denominator /= 2;
      ++precision;
    }
    int fives = 0;
    while (denominator % 5 == 0) {
      denominator /= 5;
      ++fives;
    }
    if (denominator != 1)
      precision = 18;
    else if (fives > precision)
      precision = fives;

    basic_memory_buffer<Char> fraction;
    if (precision > 0) {
      long double ticks;
      using rep = typename Duration::rep;
      if (std::is_integral<rep>::value) {
        using common_type = typename std::common_type<rep, std::intmax_t>::type;
        ticks = static_cast<long double>(
            static_cast<common_type>(val.time_since_epoch().count()) %
            static_cast<common_type>(Duration::period::den));
      } else {
        ticks = std::fmod(
            static_cast<long double>(val.time_since_epoch().count()),
            static_cast<long double>(Duration::period::den));
      }
      const auto den = static_cast<long double>(Duration::period::den);
      auto fractional_seconds =
          std::fmod(ticks * Duration::period::num, den) / den;
      if (fractional_seconds < 0) fractional_seconds += 1;

      std::uint64_t scale = 1;
      for (int i = 0; i < precision; ++i) scale *= 10;
      auto digits = static_cast<std::uint64_t>(fractional_seconds * scale + 0.5L);
      if (digits >= scale) digits = 0;
      fraction.push_back('.');
      auto divisor = scale / 10;
      for (int i = 0; i < precision; ++i) {
        fraction.push_back(static_cast<Char>('0' + digits / divisor));
        digits %= divisor;
        if (i + 1 < precision) divisor /= 10;
      }
    }

    basic_memory_buffer<Char> format;
    auto it = this->specs.begin();
    auto end = this->specs.end();
    while (it != end) {
      if (*it != '%' || precision == 0) {
        format.push_back(*it++);
        continue;
      }
      format.push_back(*it++);
      if (it == end) break;
      auto spec = *it++;
      format.push_back(spec);
      if (spec == '%') continue;
      bool fractional = spec == 'S' || spec == 'T';
      if (spec == 'O' || spec == 'E') {
        if (it != end) {
          spec = *it++;
          format.push_back(spec);
          fractional = spec == 'S' || spec == 'T';
        }
      }
      if (fractional) format.append(fraction.begin(), fraction.end());
    }

    formatter<std::tm, Char> tm_formatter;
    tm_formatter.specs = basic_string_view<Char>(format.data(), format.size());
    return tm_formatter.format(time, ctx);
  }
};

