template <typename Char, typename Duration>
struct formatter<std::chrono::time_point<std::chrono::system_clock, Duration>,
                 Char> : formatter<std::tm, Char> {
  template <typename FormatContext>
  auto format(std::chrono::time_point<std::chrono::system_clock, Duration> val,
              FormatContext& ctx) -> decltype(ctx.out()) {
    using precision = std::integral_constant<
        int, detail::chrono_fractional_precision(Duration::period::den)>;
    const auto fraction = [&]() {
      if (precision::value == 0) return std::int64_t(0);
      using scale = detail::chrono_pow10<precision::value>;
      using fractional_duration =
          std::chrono::duration<std::int64_t, std::ratio<1, scale::value>>;
      auto elapsed = val.time_since_epoch();
      auto remainder = elapsed - std::chrono::duration_cast<std::chrono::seconds>(elapsed);
      auto value = std::chrono::duration_cast<fractional_duration>(remainder).count();
      return value < 0 ? value + scale::value : value;
    }();

    auto format = this->specs;
    basic_memory_buffer<Char> tm_format;
    auto append_fraction = [&] {
      if (precision::value == 0) return;
      tm_format.push_back('.');
      auto divisor = detail::chrono_pow10<precision::value>::value / 10;
      for (; divisor > 0; divisor /= 10) {
        tm_format.push_back(static_cast<Char>('0' + fraction / divisor % 10));
      }
    };
    for (auto it = format.begin(); it != format.end(); ++it) {
      if (*it != '%' || it + 1 == format.end()) {
        tm_format.push_back(*it);
        continue;
      }
      tm_format.push_back(*it++);
      if (*it == '%') {
        tm_format.push_back(*it);
        continue;
      }
      if (*it == 'E' || *it == 'O') {
        tm_format.push_back(*it++);
        if (it == format.end()) break;
      }
      if (*it == 'T' && precision::value != 0) {
        tm_format.append("%H:%M:%S");
        append_fraction();
      } else {
        tm_format.push_back(*it);
        if (*it == 'S') append_fraction();
      }
    }

    std::tm time = localtime(std::chrono::time_point<std::chrono::system_clock>(val));
    formatter<std::tm, Char> tm_formatter;
    tm_formatter.specs = basic_string_view<Char>(tm_format.data(), tm_format.size());
    return tm_formatter.format(time, ctx);
  }
};

