    std::tm time = localtime(
        std::chrono::time_point_cast<std::chrono::system_clock::duration>(val));
    const int precision =
        detail::fractional_second_precision(Duration::period::den);
    basic_memory_buffer<Char> format_specs;
    auto append_fraction = [&] {
      if (precision == 0) return;
      *std::back_inserter(format_specs) = '.';
      using common_duration =
          typename std::common_type<Duration, std::chrono::seconds>::type;
      auto elapsed = common_duration(val.time_since_epoch());
      auto whole_seconds = std::chrono::duration_cast<std::chrono::seconds>(elapsed);
      auto fraction = elapsed - whole_seconds;
      if (fraction < common_duration::zero()) fraction += std::chrono::seconds(1);
      if (precision <= 9) {
        auto nanoseconds = std::chrono::duration_cast<std::chrono::nanoseconds>(fraction).count();
        std::uint64_t value = static_cast<std::uint64_t>(nanoseconds);
        std::uint64_t divisor = 100000000;
        for (int i = 0; i < precision; ++i) {
          format_specs.push_back(static_cast<Char>('0' + (value / divisor) % 10));
