template <typename Duration> int fractional_second_precision() {
  auto denominator = Duration::period::den;
  int twos = 0;
  int fives = 0;
  while (denominator % 2 == 0) {
    denominator /= 2;
    ++twos;
  }
  while (denominator % 5 == 0) {
    denominator /= 5;
    ++fives;
  }
  if (denominator != 1 || (std::max)(twos, fives) > 18) return 6;
  return (std::max)(twos, fives);
}

template <typename Char, typename Duration>
void append_fractional_seconds(basic_memory_buffer<Char>& format,
                               Duration duration, int precision) {
  if (precision == 0) return;
  auto seconds = std::chrono::duration_cast<std::chrono::seconds>(duration);
  auto remainder = duration - seconds;
  if (remainder < Duration::zero()) remainder += std::chrono::seconds(1);
  using fractional_seconds =
      std::chrono::duration<std::int64_t,
                            std::ratio<1, 1000000000000000000LL>>;
  auto fraction =
      std::chrono::duration_cast<fractional_seconds>(remainder).count();
  for (int i = precision; i < 18; ++i) fraction /= 10;
  char digits[18];
  for (int i = precision - 1; i >= 0; --i) {
    digits[i] = static_cast<char>('0' + fraction % 10);
    fraction /= 10;
  }
  format.push_back('.');
  for (int i = 0; i < precision; ++i)
    format.push_back(static_cast<Char>(digits[i]));
}

template <typename Char, typename Duration>
struct formatter<std::chrono::time_point<std::chrono::system_clock, Duration>,
                 Char> : formatter<std::tm, Char> {
  template <typename FormatContext>
  auto format(std::chrono::time_point<std::chrono::system_clock, Duration> val,
              FormatContext& ctx) -> decltype(ctx.out()) {
    auto time_point = std::chrono::time_point_cast<
        std::chrono::system_clock::duration>(val);
    std::tm time = localtime(time_point);
    auto precision = fractional_second_precision<Duration>();
    auto format = basic_memory_buffer<Char>();
    auto begin = this->specs.begin();
    auto end = this->specs.end();
    auto append_fraction = [&] {
      append_fractional_seconds(format, val.time_since_epoch(), precision);
    };
    for (auto it = begin; it != end;) {
      if (*it != '%') {
        format.push_back(*it++);
        continue;
      }
      format.push_back(*it++);
      if (it == end) break;
      auto c = *it++;
      if (c == 'T') {
        const Char time_format[] = {'H', ':', '%', 'M', ':', '%', 'S'};
        format.push_back('%');
        for (auto ch : time_format) format.push_back(ch);
        append_fraction();
      } else {
        format.push_back(c);
        if ((c == 'E' || c == 'O') && it != end) {
          auto spec = *it++;
          format.push_back(spec);
          if (spec == 'S') append_fraction();
        } else if (c == 'S') {
          append_fraction();
        }
      }
    }
    auto tm_formatter = formatter<std::tm, Char>();
    tm_formatter.specs = {format.data(), format.size()};
    return tm_formatter.format(time, ctx);
  }
};

