template <typename Char, typename Duration>
struct formatter<std::chrono::time_point<std::chrono::system_clock, Duration>,
                 Char> : formatter<std::tm, Char> {
 private:
  static int fractional_precision() {
    auto denominator = Duration::period::den;
    int twos = 0, fives = 0;
    while (denominator % 2 == 0) {
      denominator /= 2;
      ++twos;
    }
    while (denominator % 5 == 0) {
      denominator /= 5;
      ++fives;
    }
    if (denominator != 1) return 18;
    return twos > fives ? twos : fives;
  }

  template <typename OutputIt>
  static void append_fraction(OutputIt out, int precision,
                              long double fraction) {
    auto value = detail::format_duration_value<Char>(out, fraction, precision);
    (void)value;
  }

 public:
  template <typename FormatContext>
  auto format(std::chrono::time_point<std::chrono::system_clock, Duration> val,
              FormatContext& ctx) const -> decltype(ctx.out()) {
    auto precision = fractional_precision();
    basic_memory_buffer<Char> fraction_buf;
    if (precision > 0) {
      auto whole_seconds =
          std::chrono::duration_cast<std::chrono::seconds>(val.time_since_epoch());
      auto remainder = val.time_since_epoch() - whole_seconds;
      if (remainder < Duration::zero()) remainder += std::chrono::seconds(1);
      auto fraction = std::chrono::duration<long double>(remainder).count();
      auto out = std::back_inserter(fraction_buf);
      append_fraction(out, precision, fraction);
    }

    basic_memory_buffer<Char> format_buf;
    auto begin = this->specs.begin(), end = this->specs.end();
    while (begin != end) {
      if (*begin != '%') {
        format_buf.push_back(*begin++);
        continue;
      }
      format_buf.push_back(*begin++);
      if (begin == end) break;
      if (*begin == '%' ) {
        format_buf.push_back(*begin++);
        continue;
      }
      if (*begin == 'E' || *begin == 'O') {
        format_buf.push_back(*begin++);
        if (begin == end) break;
      }
      auto specifier = *begin++;
      format_buf.push_back(specifier);
      if ((specifier == 'S' || specifier == 'T') && precision > 0) {
        format_buf.push_back('.');
        format_buf.append(fraction_buf.begin() + 2, fraction_buf.end());
      }
    }

    formatter<std::tm, Char> tm_formatter;
    tm_formatter.specs = basic_string_view<Char>(format_buf.data(),
                                                  format_buf.size());
    std::tm time = localtime(val);
    return tm_formatter.format(time, ctx);
  }
};

