template <typename Period> inline int fractional_seconds_precision() {
  auto denominator = Period::den;
  int twos = 0;
  int fives = 0;
  while (denominator % 2 == 0 && denominator > 1) {
    denominator /= 2;
    ++twos;
  }
  while (denominator % 5 == 0 && denominator > 1) {
    denominator /= 5;
    ++fives;
  }
  if (denominator != 1) return 6;
  int precision = (std::max)(twos, fives);
  return precision > 18 ? 6 : precision;
}

