// double. A float significand has 29 fewer bits than a double significand.
void compute_float_boundaries(fp& lower, fp& upper) const {
  const int float_significand_size = 23;
  const int significand_shift = double_significand_size - float_significand_size;
  const uint64_t float_implicit_bit = 1ull << float_significand_size;
  const uint64_t float_f = f >> significand_shift;
  const int float_e = e + significand_shift;
  // The minimum normal float has the same spacing below and above it. Other
  // exact powers of two have half-sized spacing below.
  const bool lower_boundary_is_closer =
      float_f == float_implicit_bit && float_e > -149;
  lower = lower_boundary_is_closer
              ? fp((float_f << 2) - 1, float_e - 2)
              : fp((float_f << 1) - 1, float_e - 1);
  upper = normalize<1>(fp((float_f << 1) + 1, float_e - 1));
  lower.f <<= lower.e - upper.e;
  lower.e = upper.e;
}

